/**
 * "Blocked by" links between issues. Every method takes `orgId` first.
 */
import { and, asc, eq, inArray, isNull, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { IsoTimestamp, IssueId, OrgId, UserId } from "@/types/common";
import type { IssueDependency } from "@/types/issue";
import type { IssueDependencyRow } from "@/server/db";

function toIssueDependency(row: IssueDependencyRow): IssueDependency {
  return {
    orgId: row.orgId as OrgId,
    issueId: row.issueId as IssueId,
    blockerId: row.blockerId as IssueId,
    createdBy: row.createdBy as UserId,
    createdAt: row.createdAt as IsoTimestamp,
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .returning()
    .get();

  if (row) return toIssueDependency(row);

  const existing = await findDependency(orgId, issueId, blockerId);
  if (!existing) throw new Error(`Dependency ${issueId}→${blockerId} not stored`);
  return existing;
}

/** Resolves `true` when a link was actually removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const result = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .run();
  return result.changes > 0;
}

/** Ids of every issue `issueId` is blocked by, archived or not. */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all();
  return rows.map((row) => row.blockerId as IssueId);
}

/** Ids of every issue blocked by `blockerId`. */
export async function listBlockedIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => row.issueId as IssueId);
}

/** Live blocker ids of `issueId`, ordered by issue number. */
export async function listLiveBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
