/**
 * Issue dependencies ("blocked by" links): linking rules, the completion gate and the unblocked notification.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised when an issue is moved to `done` while open blockers remain. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(
      `Issue ${issueId} is blocked by ${blockerIds.length} open issue(s): ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

export type BlockerLinkInput = {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
};

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Open: not archived and neither `done` nor `canceled`. */
export function isOpenBlocker(issue: Issue): boolean {
  return issue.archivedAt === null && !isClosedStatus(issue.status);
}

/**
 * The completion gate. Called by every status-changing path before a write;
 * only a move to `done` is gated.
 */
export async function assertCanTransition(
  orgId: OrgId,
  issueId: IssueId,
  to: IssueStatus,
): Promise<void> {
  if (to !== "done") return;
  const open = await dependencyRepo.listOpenBlockerIds(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(issueId, open);
}

export async function addBlocker(
  actor: Actor,
  input: BlockerLinkInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }

  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  if (await reaches(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${issue.id} blocked by ${blocker.id} would create a dependency cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: BlockerLinkInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    issue.id,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const ids = await dependencyRepo.listLiveBlockerIds(orgId, issue.id);
  const blockers: Issue[] = [];
  for (const id of ids) {
    const blocker = await issueRepo.findIssueById(orgId, id);
    if (blocker && blocker.archivedAt === null) blockers.push(blocker);
  }
  return blockers.sort((a, b) => a.number - b.number);
}

/** True when `to` is reachable from `from` by following "blocked by" links. */
async function reaches(
  orgId: OrgId,
  from: IssueId,
  to: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  let frontier: readonly IssueId[] = [from];

  while (frontier.length > 0) {
    const links = await dependencyRepo.listDependenciesForIssues(
      orgId,
      frontier,
    );
    const next: IssueId[] = [];
    for (const link of links) {
      if (link.blockerId === to) return true;
      if (!seen.has(link.blockerId)) {
        seen.add(link.blockerId);
        next.push(link.blockerId);
      }
    }
    frontier = next;
  }
  return false;
}

/**
 * A blocker just went from open to closed: tell the assignee of every live,
 * still-open issue it blocked that has no open blocker left.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await dependencyRepo.listBlockedIds(orgId, blockerId);

  for (const blockedId of blockedIds) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || !isOpenBlocker(blocked)) continue;
    if (blocked.assigneeId === null) continue;

    const open = await dependencyRepo.listOpenBlockerIds(orgId, blocked.id);
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "Your issue is unblocked",
      body: `Issue ${blocked.title} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

/** Attached by `event-registry`; returns the detach handle. */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

