import * as issueService from "@/server/services/issue-service";
import * as dep from "@/server/services/issue-dependency-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("deps");
  const a = t.actors.admin;
  const A = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "Issue A" }));
  const B = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "Issue B" }));
  const C = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "Issue C" }));
  await issueService.assignIssue(a, { orgId: t.org.id, issueId: A.id, assigneeId: t.actors.member.userId });
  await dep.addBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id });
  const again = await dep.addBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id });
  expect(again.blockerId).toBe(B.id);
  await dep.addBlocker(a, { orgId: t.org.id, issueId: B.id, blockerId: C.id });
  await expect(dep.addBlocker(a, { orgId: t.org.id, issueId: C.id, blockerId: A.id })).rejects.toThrow();
  await expect(dep.addBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: A.id })).rejects.toThrow();
  expect((await dep.listBlockers(a, t.org.id, A.id)).map((i) => i.id)).toEqual([B.id]);
  await expect(issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: A.id, status: "done" })).rejects.toBeInstanceOf(dep.IssueBlockedError);
  await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: B.id, status: "canceled" });
  const page = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.actors.member.userId } as never);
  console.log(JSON.stringify(page.items.map((n) => [n.kind, n.href, n.actorId])));
  expect(page.items.filter((n) => n.kind === "issue_unblocked")).toHaveLength(1);
  await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: A.id, status: "done" });
  expect(await dep.removeBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id })).toBe(true);
  expect(await dep.removeBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id })).toBe(false);
});
EOF
